#include <iostream>
using namespace std;

int main() {   //@ @layout open:visualizer
    int sum = 0;   //@ @tts [next] 先準備 sum
    for (int i = 1; i <= 5; i++) {   //@ @tts [continue] 這個迴圈不是重點，直接跳到下一個斷點
        sum += i;
    }
    cout << sum << endl;   //@ @guide {sum} @tts [next] 迴圈全部跑完，sum 是 {sum}
    return 0;   //@ @tts [continue] 程式結束
}
